    crate::testport::assert_eq(fw_count(nfw), 3, "one word became three");
    crate::testport::assert_eq(fv_get(fv, 2, 0), 0, "all in group 0");
    crate::testport::assert_eq(crate::port::cells_at(nfw, 1), 0, "the first one's extent is OCR's");
    crate::testport::assert_eq(crate::port::cells_at(nfw, 3), 250, "to here");
