#[test]
fn test_ocr_only_groups_are_dropped_held_or_nothing() {
    let fw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let feats: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ow: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let refs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let im: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ep: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nfw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nfl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fv: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fx: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let afa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let w0: i32 = at_tword(fw, feats, et, 0, 0, 0, 1000, 0, 104, 101);
    let o0: i32 = at_oword(ow, feats, et, 0, 900, 0, 104, 101, 0);
    let o1: i32 = at_oword(ow, feats, et, 5000, 5900, 900, 88, 89, 0);
    let o2: i32 = at_oword(ow, feats, et, 6000, 6900, 0, 90, 91, 0);
    at_line3(fl, 0, 1);
    ep_new(ep, 1, 20000, 20000);
    // a small image holds the third OCR word's box (the area of the page is 400e6; the image 50e6: 125 per mille)
    im_new(im, 1, 5900, 0, 8000, 1000, 0, 10, 10);
    at_group(cg, refs, w0, 1, o0, 1, 1000);
    let g1: i32 = at_ocr_only_group(cg, refs, o1);
    let g2: i32 = at_ocr_only_group(cg, refs, o2);
    crate::testport::assert_eq(g1, 1, "the second group");
    crate::testport::assert_eq(g2, 2, "the third group");
    cg_set(cg, g1, 1, 5000);
    cg_set(cg, g1, 3, 5900);
    cg_set(cg, g2, 1, 6000);
    cg_set(cg, g2, 3, 7000);
    at_run(cg, refs, fw, fl, et, feats, ow, im, ep, nfw, nfl, fv, fx, afa);
    crate::testport::assert_eq(fw_count(nfw), 1, "only the text layer's word is in the flow: the ghost and the figure's word are not");
    crate::testport::assert_eq(fa_count(afa), 1, "one ghost is set aside");
    crate::testport::assert_eq(fa_get(afa, 0, 5), dr_ocr_ghost(), "as an ocr-ghost");
    crate::testport::assert_eq(fa_get(afa, 0, 9), 1, "from group 1");
    crate::testport::assert_eq(fa_get(afa, 0, 10), 170, "by rule 170");
    crate::testport::assert_eq(fa_get(afa, 0, 7), 1, "whose OCR word is row 1");
    crate::testport::assert_eq(cg_get(cg, g2, cgf_flags()), 2 + plg_in_figure(), "the figure's word says it is in a figure");
    crate::testport::assert_eq(cg_get(cg, g1, cgf_flags()), 2, "and the ghost does not");
}
#[test]
fn test_the_ghosts_of_a_line_are_one_ledger_row() {
    let afa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ow: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let feats: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tmp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let a: i32 = at_oword(ow, feats, et, 0, 100, 900, 88, 89, 0);
    let b: i32 = at_oword(ow, feats, et, 200, 300, 900, 90, 91, 0);
    let c: i32 = at_oword(ow, feats, et, 400, 500, 900, 92, 93, 0);
    ow_set(ow, a, 13, 0);
    ow_set(ow, b, 13, 0);
    ow_set(ow, c, 13, 1);
    // three dropped groups: two on OCR line 0, one on line 1
    fa_new(afa, 1, 0, 100, 100, 800, dr_ocr_ghost(), ea_owords(), a);
    fa_new(afa, 1, 200, 100, 300, 800, dr_ocr_ghost(), ea_owords(), b);
    fa_new(afa, 1, 400, 100, 500, 800, dr_ocr_ghost(), ea_owords(), c);
    crate::testport::assert_eq(ar_write(afa, ow, et, ledger, text, tmp, tt), 2, "two ledger rows");
    crate::testport::assert_eq(ledger_count(ledger), 2, "in the ledger");
    crate::testport::assert_eq(ledger_reason(ledger, 0), dr_ocr_ghost(), "an ocr-ghost");
    crate::testport::assert_eq(ledger_x1(ledger, 0), 300, "the first row spans both words");
    crate::testport::assert_eq(ledger_text_len(ledger, 0), 5, "`XY ZZ`: the words joined by a space");
    crate::testport::assert_eq(ledger_text_len(ledger, 1), 2, "the second is one word");
}
pub(crate) fn at_block(mut nodes: &mut crate::port::Cells, mut regions: &mut crate::port::Cells, mut text: &mut crate::port::Cells, x0: i32, y0: i32, x1: i32, y1: i32, a: i32) -> i32 {
    // A paragraph of page 1 over a box with one inline text of one letter; answers the paragraph's row.
    let p: i32 = node_new(nodes, nk_paragraph(), 0);
    let t: i32 = node_new(nodes, nk_text(), p);
    let ts: i32 = crate::port::cells_len(text);
    crate::port::cells_push(text, a);
    node_set_text(nodes, t, ts, 1);
    node_add_region(nodes, regions, p, 1, x0, y0, x1, y1);
    node_add_src(nodes, p, sr_text());
    node_add_src(nodes, t, sr_text());
    return p;
}
#[test]
fn test_the_model_says_where_ocr_won_and_changes_nothing_else() {
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nfw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fv: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let feats: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    model_init(nodes, attrs, regions, text, pages, ledger, layout);
    // two paragraphs: the first over words 0 and 1, the second over word 2
    let pa: i32 = at_block(nodes, regions, text, 0, 0, 2000, 1000, 65);
    let pb: i32 = at_block(nodes, regions, text, 0, 2000, 1000, 3000, 66);
    at_tword(nfw, feats, et, 0, 0, 0, 1000, 0, 97, 97);
    at_tword(nfw, feats, et, 1000, 0, 0, 1000, 0, 98, 98);
    // word 2 sits in the second paragraph's box
    let w2: i32 = at_tword(nfw, feats, et, 0, 0, 0, 1000, 0, 99, 99);
    wd_set(nfw, w2, 2, 2200);
    wd_set(nfw, 2, 4, 2800);
    fv_new(fv, 0, 1, 101, 900, 0);
    fv_new(fv, 0, 1, 101, 900, 0);
    fv_new(fv, 1, 1, 101, 900, 0);
    crate::testport::assert_eq(ar_tag(nodes, regions, nfw, fv), 0, "nothing was OCR's: nothing is tagged");
    crate::testport::assert_eq(node_src(nodes, pa), sr_text(), "the first paragraph is as it was");
    crate::testport::assert_eq(node_src(nodes, pb), sr_text(), "so is the second");
    // now OCR wins the third word
    crate::port::cells_set(fv, 17, 4);
    crate::port::cells_set(fv, 19, 800);
    crate::port::cells_set(fv, 20, 4);
    crate::testport::assert_eq(ar_tag(nodes, regions, nfw, fv), 1, "one block was tagged");
    crate::testport::assert_eq(node_src(nodes, pa), sr_text(), "the paragraph OCR did not touch is not changed");
    crate::testport::assert_eq(node_flags(nodes, pa), 0, "nor flagged");
    crate::testport::assert_eq(node_src(nodes, pb), sr_ocr(), "the one OCR read in full is `ocr`, not `text`");
    crate::testport::assert_eq(node_flags(nodes, pb), fl_text_layer_suspect(), "flagged text-layer-suspect");
    crate::testport::assert_eq(node_conf(nodes, pb), 800, "at OCR's confidence");
    crate::testport::assert_eq(node_src(nodes, pb + 1), sr_ocr(), "and its inline follows");
}
